    public function compareVersions($renderType = 'Inline')
    {
        try {
            $current_docversion = DocsControlCambioPeer::getCurrentVersionDoc($this->getConsecutivoId(), $this->getModuloId());

            if (empty($current_docversion) || empty($this)) {
