            $newContent = $current_docversion->getContenidoText();

            if ($oldContent == null || $newContent == null) {
                throw new Exception("Una o ambas versiones no existen");
            }
            //*********************************************************************************************
            $oldBlocks = $this->extraerBloquesParaComparar($oldContent);
            $newBlocks = $this->extraerBloquesParaComparar($newContent);
            //*********************************************************************************************
            $oldTexts = array_map(function ($bloque) { return $bloque['text']; }, $oldBlocks);
            $newTexts = array_map(function ($bloque) { return $bloque['text']; }, $newBlocks);
            //*********************************************************************************************
            if ($oldTexts === $newTexts) {
